298|/// Simple 64-bit hash for output comparison.
299|fn simple_hash<T: Hash + ?Sized>(data: &T) -> u64 {
300|    let mut s = DefaultHasher::new();
301|    data.hash(&mut s);
302|    s.finish()
303|}
