314|/// Discover all .gguf files in a directory (recursively).
315|fn discover_models(dir: &Path) -> Result<Vec<PathBuf>> {
316|    let mut models = Vec::new();
317|
318|    if dir.is_dir() {
319|        for entry in std::fs::read_dir(dir)? {
320|            let entry = entry?;
321|            let path = entry.path();
322|
323|            match path.extension().and_then(|s| s.to_str()) {
324|                Some("gguf") => models.push(path),
325|                _ if path.is_dir() => {
326|                    models.extend(discover_models(&path)?);
327|                }
328|                _ => {}
329|            }
330|        }
331|    } else if dir.exists() && path_ends_with(dir, ".gguf") {
332|        models.push(dir.to_path_buf());
333|    }
334|
335|    Ok(models)
336|}
